/**
 * Single source of truth for personal / factual data.
 * Everything here comes from the CV (public/cv/Derick-Putini-CV.pdf).
 *
 * To publish your profiles, just fill the empty strings in `links`:
 * the buttons across the site become active automatically.
 */

export interface Certification {
  id: string
  name: string
  issuer: string
  hours: number
  year: number
}

export interface Profile {
  name: string
  firstName: string
  lastName: string
  email: string
  phone: string
  phoneHref: string
  /** CV PDFs generated by cv-source/build.mjs — one per site language. */
  cv: { pt: string; en: string }
  cvVersion: string
  location: {
    city: string
    region: string
    country: { en: string; pt: string }
    /** Approximate coordinates of Santo André, SP — used only as a typographic detail. */
    coords: string
    timeZone: string
  }
  links: {
    linkedin: string
    github: string
  }
  education: {
    institution: string
    semester: number
    expectedYear: number
    expectedMonth: { pt: string; en: string }
  }
  certifications: Certification[]
}

